    {"새찬송가": "455", "통일찬송가": "372", "제목": "내 영혼에 햇빛 비치니", "선정이유": "어두운 시험 속에서도 영혼의 기쁨을 노래한다"},
    {"새찬송가": "382", "통일찬송가": "435", "제목": "내 주를 가까이 하게 함은", "선정이유": "시험을 통해 주께 더 가까이 나아가는 은혜를 고백한다"}
