    {"구분": "사라의 웃음", "내용": "사라는 아들을 주시겠다는 하나님의 약속에 웃으며 의심했다(창 18:12). 그러나 하나님은 약속대로 이삭을 주셨다", "그리스도연결": "하나님의 약속은 인간의 의심에도 불구하고 성취된다. 그러나 의심은 축복을 경험하는 기쁨을 지연시킨다"}
