    {"대지": "서론", "내용": "야고보는 의심하는 자를 '두 마음을 품은 자'로 정의한다. 이 독특한 표현은 성경에서 야고보만 사용한 것으로 믿음의 이중성에 대한 강력한 경고이다", "예화_적용": "키에르케고르는 '마음의 순결은 한 가지를 원하는 것'이라 했다. 두 마음은 순결의 반대이다"},
    {"대지": "1대지: 두 마음의 정체 (진단)", "내용": "딥쉬코스는 하나님과 세상, 믿음과 의심, 영과 육 사이에서 분열된 상태이다. 한쪽을 완전히 택하지도 버리지도 못하는 상태이다", "예화_적용": "두 갈래 길에서 한 발씩 내딛으면 결국 어디에도 도달하지 못한다. 결단이 필요하다"},
    {"대지": "2대지: 모든 일에 정함이 없음 (증상)", "내용": "두 마음의 결과는 기도뿐 아니라 '모든 일'에 나타난다. 직장, 가정, 교회, 관계 모든 영역에서 불안정해진다", "예화_적용": "집의 기초가 갈라지면 온 집이 흔들린다. 마음의 기초가 갈라지면 삶 전체가 흔들린다"},
    {"대지": "3대지: 결단의 부르심 (처방)", "내용": "야고보는 4:8에서 '두 마음을 품은 자들아 마음을 성결케 하라'고 처방을 제시한다. 치유의 방법은 하나님께로의 온전한 결단이다", "예화_적용": "여호수아는 '너희가 섬길 자를 오늘날 택하라'(수 24:15)고 선언했다. 결단의 시간은 바로 오늘이다"},
    {"대지": "결론", "내용": "두 마음의 삶은 가장 비참한 삶이다. 세상도 하나님도 온전히 누리지 못하는 삶이다. 오늘 한 마음으로 하나님께 돌아가자", "예화_적용": "어거스틴은 회심 전 두 마음으로 고통받다가 '들어 읽으라'는 음성을 듣고 한 마음으로 결단했다. 그 결단이 교회 역사를 바꾸었다"}
