    {"대지": "서론", "내용": "야고보는 9절의 낮은 형제에 이어 부한 형제에게 말한다. 놀랍게도 부자에게는 '높음'이 아니라 '낮아짐'을 자랑하라고 한다. 이것은 복음의 역설이다", "예화_적용": "록펠러는 임종 시 '내 재산이 다 무슨 소용인가'라고 했다고 전해진다. 세상의 부는 영원을 앞두면 무의미해진다"},
    {"대지": "1대지: 부한 형제에게 (대상)", "내용": "야고보는 부자를 정죄하지 않고 '형제'라 부른다. 부 자체가 죄가 아니다. 문제는 부에 대한 태도이다", "예화_적용": "칼은 요리에 쓰이면 유익하고 사람을 해치면 해롭다. 부도 사용하기에 따라 축복이 되거나 저주가 된다"},
    {"대지": "2대지: 낮아짐을 자랑하라 (태도)", "내용": "부자의 낮아짐은 부의 한계를 인정하고 하나님 앞에 겸비하는 것이다. 부로 교만하지 않고 청지기 의식을 갖는 것이다", "예화_적용": "청지기는 주인의 재산을 맡은 자이지 소유한 자가 아니다. 부자는 하나님의 재산의 청지기이다"},
    {"대지": "3대지: 풀의 꽃과 같이 (경고)", "내용": "풀의 꽃은 아름답지만 곧 시든다. 세상의 부도 이와 같다. 오늘의 풍요가 내일의 보장이 되지 않는다", "예화_적용": "2008년 금융위기 때 하루아침에 재산을 잃은 사람들이 많았다. 부의 영속성은 환상이다"},
    {"대지": "결론", "내용": "낮은 자는 높음을, 높은 자는 낮아짐을 자랑하라. 복음은 세상의 가치를 뒤집으며 영원한 가치를 제시한다. 지나가지 않는 하늘의 보화에 투자하자", "예화_적용": "선교사 짐 엘리엇은 '잃을 수 없는 것을 얻기 위해 지킬 수 없는 것을 버리는 것은 어리석은 자가 아니다'라고 했다"}
