    {"상황": "설교에 감동은 받지만 삶으로 이어지지 않는 성도", "성경원리": "감동은 행동이 아니다. 눈물은 순종이 아니다. 야고보는 말씀을 '행하라'는 구체적 명령을 내린다. 감정적 반응을 넘어 행동적 순종으로 나아가야 한다", "실제적용": "설교 후 구체적 행동 계획을 세우도록 안내하라. 누구에게 사과할 것인지, 무엇을 나눌 것인지, 어떤 습관을 바꿀 것인지 구체적으로 정하라"}
