    {"원어": "ἄσπιλος (아스필로스)", "의미_문법": "점 없는, 물들지 않는 - 형용사 남성 단수 대격. 얼룩 없이 깨끗한", "설교포인트": "세속에 물들지 않는다는 것은 세상과 단절이 아니라 세상 속에서도 거룩을 유지하는 것이다. 세상에 살되 세상에 물들지 않는 것이다"}
